CREATE TABLE ibexa_url_alias_ml (parent INT DEFAULT 0 NOT NULL, text_md5 VARCHAR(32) DEFAULT '' NOT NULL, action TEXT NOT NULL, action_type VARCHAR(32) DEFAULT '' NOT NULL, alias_redirects INT DEFAULT 1 NOT NULL, id INT DEFAULT 0 NOT NULL, is_alias INT DEFAULT 0 NOT NULL, is_original INT DEFAULT 0 NOT NULL, lang_mask BIGINT DEFAULT 0 NOT NULL, link INT DEFAULT 0 NOT NULL, text TEXT NOT NULL, PRIMARY KEY(parent, text_md5));
